ANCESTRY="row=json.loads(_result)\nfrom modern_projection.pyreact.debug import _type_name\nscreen=api.GetTopScreen()\ndef flatten(fiber):\n return [fiber]+[item for child in fiber.child_fibers for item in flatten(child)]\nfibers=flatten(screen._root_fiber) if screen is not None else []\nentries=[]\nfor key,entry in (s.portal_controls.registry.items() if s.portal_controls and screen is not None else ()):\n renderer=entry.get('renderer')\n if renderer is None:continue\n closure=list(zip(renderer.show.func_code.co_freevars,\n  [cell.cell_contents for cell in (renderer.show.func_closure or ())]))\n slots=[]\n for index,ref in enumerate(entry['surfaces']):\n  matches=[fiber for fiber in fibers if fiber.ref is ref]\n  assert len(matches)==1,(repr(key),index,len(matches))\n  fiber=matches[0]\n  control=ref.current\n  assert control is not None\n  path=fiber.native_path\n  prefixes=[]\n  current=path\n  while current:\n   prefixes.append(current)\n   current=current.rsplit('/',1)[0] if '/' in current else ''\n  ancestors=[]\n  for prefix in prefixes:\n   parent=fiber.host.GetBaseUIControl(prefix)\n   ancestors.append({'path':prefix,'exists':parent is not None,\n    'native_visible':parent.GetVisible() if parent is not None else None,\n    'native_size':parent.GetSize() if parent is not None else None,\n    'native_position':parent.GetGlobalPosition() if parent is not None else None})\n  slots.append({'slot':index,'surface_fiber_key':repr(fiber.key),'surface_type':_type_name(fiber),\n   'surface_path':path,'direct_surface_visible':control.GetVisible(),\n   'renderer_cached_visible':renderer.visible[index],\n   'doll_direct_visible':entry['dolls'][index].current.GetVisible(),\n   'native_model_id':renderer.dolls[index].GetModelId(),\n   'ancestors_from_actual_surface':ancestors})\n entries.append({'key':repr(key),'front':renderer.front,'slots':slots,\n  'show_function':renderer.show.func_code.co_name,\n  'show_closure_names':[name for name,value in closure],\n  'show_closes_exact_owned_surfaces':any(value is entry['surfaces'] for name,value in closure)})\nrow['owned_surface_native_ancestry']=entries\n_result=json.dumps(row)\n"
